/** A person's grace days for a claim dated on a date: those of the grade they had then, in force then; 0 when none. */
export type GraceOn = (date: string) => number;

/** The sheet's floor in force on a date, in cents. */
export type FloorOn = (date: string) => number;

/** Open: OPEN, or PENDING, which is handled like it. */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Only open (OPEN or PENDING) and SETTLED claims count toward what is claimed and due. */
export function counts(c: Claim): boolean {
  return isOpen(c) || c.status === 'SETTLED';
}

/** Whether its due is now bound by its person's last statement: stated and not PENDING. */
export function isBound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

/**
 * Deferred: OPEN with a deferred-until date after the sheet's today. It counts in no total, is not
 * overdue, cannot be settled and is left unbound by a statement until today reaches that date.
 */
export function isDeferred(c: Claim, today: string | null): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
}

/**
 * Whether the claim counts for its person, given whether its date falls within one of their holds and
 * the sheet's today: an open claim dated within a hold does not, unless bound by a statement, nor does a deferred one.
 */
export function countsFor(c: Claim, heldOnDate: boolean, today: string | null): boolean {
  return counts(c) && (!heldOnDate || !isOpen(c) || isBound(c)) && !isDeferred(c, today);
}

/**
 * The status the claim had at the end of the date, as its status log records it: the last line dated
 * on or before it; null when it had none then (added after it). A claim with no log lines (added
 * before the log was kept) is taken to have had its status now.
 */
export function statusAt(c: Claim, date: string): ClaimStatus | null {
  if (c.log.length === 0) return c.status;
  let at: ClaimStatus | null = null;
  for (const line of c.log) if (line.date <= date) at = line.status;
  return at;
}

/**
 * Whether the claim counts for a period ending on `end`: by the status it had then (open or SETTLED),
 * less a deferred one and one still open now (OPEN or PENDING) dated within a hold and not bound, as the
 * live rules say: a claim since settled or voided is no longer kept out by a hold.
 */
export function countsAt(c: Claim, end: string, heldOnDate: boolean, today: string | null): boolean {
  const status = statusAt(c, end);
  if (status === null) return false;
  const counts = status === 'OPEN' || status === 'PENDING' || status === 'SETTLED';
  const openNow = c.status === 'OPEN' || c.status === 'PENDING';
  return counts && (!heldOnDate || !openNow || isBound(c)) && !isDeferred(c, today);
}

/** A claim's amount as cents, so sums are exact; a correction's is negative. */
export function cents(amount: string): number {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const size = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
  return negative ? -size : size;
}

/** A correction: a claim with a negative amount. Its due has no floor and no late charge. */
export function isCorrection(c: Claim): boolean {
  return cents(c.amount) < 0;
}

/**
 * The date a claim's live figures round by: a correction's corrected claim's date (found among its
 * person's claims, `theirs`), else its own.
 */
export function roundsOn(c: Claim, theirs: Claim[]): string {
  if (c.corrects === null) return c.date;
  return theirs.find((o) => o.number === c.corrects)?.date ?? c.date;
}

/** Whether a claim rounding by the given date rounds half up: dated before the policy date; else half to even. */
function halfUp(basis: string, late: Late): boolean {
  return late.policy !== null && basis < late.policy;
}

/**
 * A claim's due in cents: the due fixed when it was settled (late charge frozen in), else the greater of
 * the floor in force on its date (`floorOn`, in cents) and its figure — the rate figure bound by its
 * person's last statement, else its amount times its person's rate on its date (as `pctOn` gives it) —
 * with its late charge (by the late percent in force on each 30-day boundary) on top; a correction has
 * no floor and no charge. Null when it has none. Its live figures round by the date `basis` (see {@link roundsOn}).
 * Its grace days (`graceOn`) put off when it is overdue and its charge's 30-day boundaries.
 */
export function claimDueCents(c: Claim, pctOn: PctOn, floorOn: FloorOn, late: Late, basis: string, graceOn: GraceOn): number | null {
  if (c.settledDue !== null) return cents(c.settledDue);
  const up = halfUp(basis, late);
  const figure = figureCents(c, pctOn, up);
  if (figure === null) return null;
  const charged = figure + lateChargeCents(c, figure, late, up, graceOn);
  return isCorrection(c) ? charged : Math.max(charged, floorOn(c.date));
}

/** A claim's figure in cents: the rate figure bound by its person's last statement, else its rate figure (no floor). */
function figureCents(c: Claim, pctOn: PctOn, halfUp: boolean): number | null {
  if (isBound(c)) return c.statedDue === null ? null : cents(c.statedDue);
  const pct = pctOn(c.date);
  if (pct === null) return null;
  return dueCents(cents(c.amount), pct, halfUp);
}

/**
 * The late charge in cents on an overdue claim with the given figure, worked out per 30-day boundary: for each full
 * 30 days past its due-by plus its grace days, the late percent in force on that boundary date (the due-by plus the
 * grace plus 30, 60, 90 ... days) of it plus the charges of the boundaries before it (compounding), rounded like a
 * due, and the charges added up; 0 when not overdue or a
 * correction. Never bound by a statement.
 */
export function lateChargeCents(c: Claim, figureCents: number, late: Late, halfUp: boolean, graceOn: GraceOn): number {
  if (late.today === null || isCorrection(c) || !isOverdue(c, late.today, graceOn)) return 0;
  const dueBy = Date.parse(`${lateFrom(c, graceOn)}T00:00:00Z`);
  let total = 0;
  for (let step = 1; ; step++) {
    const boundary = new Date(dueBy + step * 30 * 86_400_000).toISOString().slice(0, 10);
    if (boundary > late.today) return total;
    total += dueCents(figureCents + total, late.pctOn(boundary), halfUp);
  }
}

/** The date (yyyy-mm-dd) past which a claim is late: its due-by plus its grace days; the due-by shown is unchanged. */
export function lateFrom(c: Claim, graceOn: GraceOn): string {
  const grace = graceOn(c.date);
  if (grace === 0) return c.dueBy;
  return new Date(Date.parse(`${c.dueBy}T00:00:00Z`) + grace * 86_400_000).toISOString().slice(0, 10);
}

/** Overdue: OPEN or PENDING, not deferred, with its due-by plus its grace days before the sheet's today. */
export function isOverdue(c: Claim, today: string | null, graceOn: GraceOn): boolean {
  return isOpen(c) && today !== null && lateFrom(c, graceOn) < today && !isDeferred(c, today);
}

/** Why a change to a claim due inside a closed period is refused. */
const CLOSED = 'No claim due inside a closed period can be changed.';

/** Why a claim dated after its person's retirement date is refused. */
export const RETIRED = 'No claim can be dated after its person\'s retirement date.';

/** Cents as an amount with two decimals; a minus sign when negative. */
export function money(cents: number): string {
  const size = Math.abs(cents);
  return `${cents < 0 ? '-' : ''}${Math.floor(size / 100)}.${String(size % 100).padStart(2, '0')}`;
}

/** What each action makes of a claim, for why it was refused. */
/** Why a void without a reason from the sheet's list is refused. */
const VOID_REASON_NEEDED = 'Choose a reason from the sheet\'s void reasons to void the claim.';

const PAST: Record<ClaimAction, string> = {
  open: 'opened', settle: 'settled', void: 'voided', approve: 'approved', reject: 'rejected',
  resettle: 're-settled', delete: 'deleted', restore: 'restored',
};

import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

interface SheetView {
  id: string;
  today: string;
  floor: string;
  terms: number;
  latePct: string;
  policyDate: string | null;
  cap: string | null;
  dated: Dated;
  archived: boolean;
  lastBatch: number | null;
}

/** A value recorded for a dated setting from a date (yyyy-mm-dd) on; null when none. */
export interface DatedValue {
  from: string;
  value: string | null;
}

/** The values recorded for each dated setting (floor, late-pct, terms, terms-<grade>, grace-<grade>, clerk-limit, cap,
 * proof-threshold, proof-threshold-<grade>, note-threshold), by key. */
export type Dated = Partial<Record<string, DatedValue[]>>;

/** The values in force before any is recorded: a key without one has none. */
const STARTING: Partial<Record<string, string>> = { floor: '1.00', 'late-pct': '0.00', terms: '14' };

/**
 * What a claim's late charge and rounding depend on: the sheet's late percent in force on a date, its today, and
 * the policy date in force (the sheet's today when blank), before which a claim's live figures round half up.
 */
export interface Late {
  pctOn: (date: string) => string;
  today: string | null;
  policy: string | null;
}

/** A claim template on the sheet: a claim made from it takes its amount (two decimals) and note then. */
export interface ClaimTemplate {
  id: number;
  name: string;
  amount: string;
  note: string;
}

/** A person on the sheet as other sections need them: who they are and whether they are retired. */
export interface PersonRef {
  id: number;
  name: string;
  retired: boolean;
}

// The signed-in user and the active sheet. Every other feature reads these to scope its calls.
/** What the people list can be sorted by on the screen. */
export type PeopleSort = 'added' | 'name' | 'grade' | 'due-total';

@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheetId = signal<string | null>(null);
  /** The sheet's today (yyyy-mm-dd): every date decision and default date uses it, never the clock. */
  readonly today = signal<string | null>(null);
  /** The values recorded for the sheet's dated settings, by key. */
  readonly dated = signal<Dated>({});
  /** The sheet's floor in force today, two decimals: a claim's live due is at least the one in force on its date. */
  readonly floor = computed(() => this.valueOn('floor', this.today()) ?? '1.00');
  /** The sheet's terms in days in force today: a claim of a grade without its own is due by its date plus those in force then. */
  readonly terms = computed(() => Number(this.valueOn('terms', this.today()) ?? '14'));
  /** The sheet's late percent in force today, two decimals: an overdue claim's due gains, for each full 30 days, the one in force on that boundary date of its figure. */
  readonly latePct = computed(() => this.valueOn('late-pct', this.today()) ?? '0.00');
  /** The clerk limit in force today, two decimals; null when none. */
  readonly clerkLimit = computed(() => this.valueOn('clerk-limit', this.today()));
  /** The sheet's policy date (yyyy-mm-dd) as set; null when blank, which means the sheet's today. */
  readonly policyDate = signal<string | null>(null);
  /** The sheet's cap in force today, two decimals: a person's due-total is at most it; null when none. */
  readonly cap = computed(() => this.valueOn('cap', this.today()));
  /** The proof threshold in force today, two decimals; null when none. */
  readonly proofThreshold = computed(() => this.valueOn('proof-threshold', this.today()));
  /** The note threshold in force today, two decimals; null when none. */
  readonly noteThreshold = computed(() => this.valueOn('note-threshold', this.today()));
  /** The late percent by date, today and policy date together, as a claim's late charge and rounding need them. */
  readonly late = computed<Late>(() => ({
    pctOn: (date) => this.valueOn('late-pct', date) ?? '0.00',
    today: this.today(),
    policy: this.policyDate() ?? this.today(),
  }));
  /** The grade's grace days in force on a date: a claim of a person of that grade then is overdue only past its due-by plus them; 0 when none. */
  graceOn(grade: string, date: string): number {
    return Number(this.valueOn(`grace-${grade}`, date) ?? '0');
  }
  /** The floor in force on a date, in cents. */
  readonly floorCentsOn = (date: string): number => {
    const [whole, frac = ''] = (this.valueOn('floor', date) ?? '1.00').split('.');
    return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
  };

  /**
   * The key's value in force on the date: the one recorded with the latest from-date on or before it,
   * else its starting value (none for a key without one); null when none.
   */
  valueOn(key: string, date: string | null): string | null {
    let found: DatedValue | undefined;
    for (const d of this.dated()[key] ?? []) {
      if (date !== null && d.from <= date && (found === undefined || d.from > found.from)) found = d;
    }
    return found !== undefined ? found.value : (STARTING[key] ?? null);
  }

  /**
   * The sheet's void reasons, in the order they were added: while any are on the list, a claim is voided
   * only with one of them. Kept by the void reasons section as it reads and adds them.
   */
  readonly voidReasons = signal<string[]>([]);

  /** The sheet's claim templates, by name. Kept by the templates section as it reads and saves them. */
  readonly templates = signal<ClaimTemplate[]>([]);

  /** The people on the sheet, in the order they were added. Kept by the people section as it reads and changes them. */
  readonly people = signal<PersonRef[]>([]);

  /** Whether a steward has archived the sheet: it stays visible and every change to it is refused. */
  readonly archived = signal(false);

  /** The number of the sheet's last bulk settle batch, or null while there has been none. */
  readonly lastBatch = signal<number | null>(null);

  /** The id of the last sheet this one was cloned to from this screen; null when none since it was loaded. */
  readonly clonedTo = signal<string | null>(null);

  /** Bumped on every sheet load, so features re-read the sheet from the store even for the same id. */
  readonly loads = signal(0);

  /** The id of the sheet this one names as its parent, as the settings last read it; null when none. */
  readonly parent = signal<string | null>(null);
  /** The month (1 to 12) a fiscal year starts in, as the settings last read it; 1 unless set. */
  readonly fiscalStartMonth = signal(1);
  /** Bumped each time the pot is saved, so the pools re-read their cuts. */
  readonly potSaves = signal(0);
  /** Bumped each time a hold is put on or the sheet's today changes, so the pools re-read their cuts. */
  readonly holdChanges = signal(0);
  /**
   * Each person's cut total in cents, by person id: their cuts as the pools show them, across every pool
   * they are a member of, added up (a pool that shows no cuts adds nothing). Kept by the pools section.
   */
  readonly cutTotals = signal<ReadonlyMap<number, number>>(new Map());
  /**
   * The as-of date (yyyy-mm-dd) the signed-in user views the sheet at, or null: while it is set every
   * figure is shown as it stood at the end of that date, with it as the sheet's today, and every change
   * is refused. It belongs to this screen, and is left as it is by loading a sheet.
   */
  readonly asOf = signal<string | null>(null);
  /** Whether retired people are listed: off when the screen opens, left as it is by loading a sheet. */
  readonly showRetired = signal(false);
  /** What the people list is sorted by on this screen: added (list order) when the screen opens, left as it is by loading a sheet. */
  readonly sortBy = signal<PeopleSort>('added');

  async signIn(name: string): Promise<void> {
    const res = await firstValueFrom(this.http.post<{ name: string }>('/api/session', { name }));
    this.user.set(res.name);
  }

  async loadSheet(id: string): Promise<void> {
    const user = this.user();
    if (!user) throw new Error('not signed in');
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
        headers: { 'X-User': user },
      }),
    );
    this.sheetId.set(res.id);
    this.today.set(res.today);
    this.dated.set(res.dated);
    this.policyDate.set(res.policyDate);
    this.archived.set(res.archived);
    this.lastBatch.set(res.lastBatch);
    this.clonedTo.set(null);
    this.loads.update((n) => n + 1);
  }

  /** View the active sheet as of a date (yyyy-mm-dd), or as it is now (null): it is loaded again. */
  async setAsOf(asOf: string | null): Promise<void> {
    const id = this.sheetId();
    if (!id) throw new Error('no sheet loaded');
    this.asOf.set(asOf);
    await this.loadSheet(id);
  }

  async setToday(today: string): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const res = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
        headers: { 'X-User': user },
      }),
    );
    if (this.sheetId() === res.id) {
      this.today.set(res.today);
      this.holdChanges.update((n) => n + 1);
    }
  }

  async archive(): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null, {
        headers: { 'X-User': user },
      }),
    );
    if (this.sheetId() === res.id) this.archived.set(res.archived);
  }

  /** Clone the active sheet to another id, one never used; a steward only. */
  async cloneTo(to: string): Promise<void> {
    const user = this.user();
    const id = this.sheetId();
    if (!user || !id) throw new Error('no sheet loaded');
    this.clonedTo.set(null);
    const res = await firstValueFrom(
      this.http.post<{ to: string }>(`/api/sheets/${encodeURIComponent(id)}/clone`, { to }, {
        headers: { 'X-User': user },
      }),
    );
    if (this.sheetId() === id) this.clonedTo.set(res.to);
  }
}

